・計画工程表：全体工程をバーチャートやネットワークで示す。
・現場組織表：現場代理人、監理技術者、担当係の編成と指揮命令系統、緊急時連絡体制。
・指定機械・主要船舶機械：使用する高所作業車、クレーン、延線機など。
・主要資材：光ケーブル、無線装置などの品名・規格・製造者と搬入時期。
・施工方法：主要工種ごとの作業手順、仮設備計画を含む。
・施工管理計画：品質管理（試験項目・頻度・判定基準）、出来形管理、工程管理、写真管理の方法。
・安全管理：安全管理組織、危険作業への対策、安全教育・訓練の計画。
・緊急時の体制及び対応：事故・災害発生時の連絡系統図と応急措置。
・交通管理：道路使用時の規制方法、交通誘導警備員の配置。
・環境対策：騒音・振動対策、近隣への配慮。
・現場作業環境の整備、再生資源の利用の促進と建設副産物の適正処理。

━━━━━━━━━━━━━━━━━━━━━━
