・★安全衛生責任者：統括安全衛生責任者が選任される現場で、★下請（関係請負人）側がそれぞれ選任する連絡役。統括安全衛生責任者との連絡、連絡事項の関係者への伝達、下請が行う作業の調整などを担う。
・★店社安全衛生管理者：統括安全衛生責任者の選任義務がない中規模現場（鉄骨造等の建築で常時20人以上50人未満など）で、元方事業者の★店社（本支店）が選任し、現場の安全衛生指導を行う（毎月1回以上の巡回指導など）。
